 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE fc fusion_compares;
BEGIN
 -- 0326 Fusion source archive guard
 PERFORM opc_assert_business_writable(p_actor_id,jsonb_build_object('sessionId',(SELECT session_id FROM fusion_compares
    WHERE id=p_compare_id AND actor_id=p_actor_id)));

  PERFORM bill2_actor(p_actor_id);
  IF p_verdict IS NULL OR p_verdict NOT IN ('clear','allow','block','unavailable') OR p_fallback IS NULL
